/**
 * International Telephone Input v17.0.19 (Simplified version for Batci FLC)
 * This is a simplified version of intl-tel-input for the plugin demo
 * For production use, replace with the full library from: https://github.com/jackocnr/intl-tel-input
 */

(function (global, factory) {
    typeof exports === 'object' && typeof module !== 'undefined' ? module.exports = factory() :
    typeof define === 'function' && define.amd ? define(factory) :
    (global = global || self, global.intlTelInput = factory());
}(this, (function () {
    'use strict';

    // Country data (simplified)
    var allCountries = [
        ["United States", "us", "1"],
        ["Canada", "ca", "1"],
        ["United Kingdom", "gb", "44"],
        ["Australia", "au", "61"],
        ["Germany", "de", "49"],
        ["France", "fr", "33"],
        ["India", "in", "91"],
        ["Japan", "jp", "81"],
        ["China", "cn", "86"],
        ["Brazil", "br", "55"],
        ["Russia", "ru", "7"],
        ["South Africa", "za", "27"],
        ["Mexico", "mx", "52"],
        ["Italy", "it", "39"],
        ["Spain", "es", "34"],
        ["Netherlands", "nl", "31"]
    ];

    // Simplified intlTelInput implementation
    function IntlTelInput(input, options) {
        this.telInput = input;
        this.options = Object.assign({
            initialCountry: 'us',
            preferredCountries: ['us', 'gb'],
            separateDialCode: false,
            autoPlaceholder: 'polite',
            formatOnDisplay: true
        }, options || {});

        this.selectedCountryData = {};
        this.init();
    }

    IntlTelInput.prototype = {
        init: function() {
            this._processCountryData();
            this._generateMarkup();
            this._setInitialState();
            this._initListeners();
        },

        _processCountryData: function() {
            this.countries = [];
            for (var i = 0; i < allCountries.length; i++) {
                var c = allCountries[i];
                this.countries.push({
                    name: c[0],
                    iso2: c[1],
                    dialCode: c[2]
                });
            }
        },

        _generateMarkup: function() {
            var input = this.telInput;
            
            // Create container
            this.container = document.createElement('div');
            this.container.className = 'iti';
            input.parentNode.insertBefore(this.container, input);
            this.container.appendChild(input);

            // Create flag container
            this.flagContainer = document.createElement('div');
            this.flagContainer.className = 'iti__flag-container';
            this.container.appendChild(this.flagContainer);

            // Create selected flag
            this.selectedFlag = document.createElement('div');
            this.selectedFlag.className = 'iti__selected-flag';
            this.selectedFlag.setAttribute('tabindex', '0');
            this.flagContainer.appendChild(this.selectedFlag);

            // Create flag
            this.selectedFlagInner = document.createElement('div');
            this.selectedFlagInner.className = 'iti__flag';
            this.selectedFlag.appendChild(this.selectedFlagInner);

            // Create dropdown arrow
            if (this.options.allowDropdown !== false) {
                this.dropdownArrow = document.createElement('div');
                this.dropdownArrow.className = 'iti__arrow';
                this.selectedFlag.appendChild(this.dropdownArrow);

                // Create country list
                this.countryList = document.createElement('ul');
                this.countryList.className = 'iti__country-list iti__hide';
                this.countryList.setAttribute('aria-expanded', 'false');
                this.container.appendChild(this.countryList);

                // Populate country list
                this._generateCountryListItems();
            }

            // Update classes
            if (this.options.allowDropdown !== false) {
                this.container.className += ' iti--allow-dropdown';
            }
        },

        _generateCountryListItems: function() {
            var self = this;
            
            this.countries.forEach(function(country, index) {
                var listItem = document.createElement('li');
                listItem.className = 'iti__country';
                listItem.setAttribute('data-dial-code', country.dialCode);
                listItem.setAttribute('data-country-code', country.iso2);
                
                var flagBox = document.createElement('div');
                flagBox.className = 'iti__flag-box';
                
                var flag = document.createElement('div');
                flag.className = 'iti__flag iti__' + country.iso2;
                flagBox.appendChild(flag);
                
                var countryName = document.createElement('span');
                countryName.className = 'iti__country-name';
                countryName.textContent = country.name;
                
                var dialCode = document.createElement('span');
                dialCode.className = 'iti__dial-code';
                dialCode.textContent = '+' + country.dialCode;
                
                listItem.appendChild(flagBox);
                listItem.appendChild(countryName);
                listItem.appendChild(dialCode);
                
                // Add click listener
                listItem.addEventListener('click', function() {
                    self._selectCountry(country.iso2);
                    self._closeDropdown();
                });
                
                self.countryList.appendChild(listItem);
            });
        },

        _setInitialState: function() {
            var initialCountry = this.options.initialCountry || 'us';
            this._selectCountry(initialCountry);
        },

        _initListeners: function() {
            var self = this;
            
            if (this.options.allowDropdown !== false) {
                // Toggle dropdown
                this.selectedFlag.addEventListener('click', function() {
                    self._toggleDropdown();
                });

                // Close dropdown when clicking outside
                document.addEventListener('click', function(e) {
                    if (!self.container.contains(e.target)) {
                        self._closeDropdown();
                    }
                });
            }

            // Format number on input
            this.telInput.addEventListener('input', function() {
                self._formatNumber();
            });
        },

        _selectCountry: function(countryCode) {
            var country = this._getCountryData(countryCode);
            if (country) {
                this.selectedCountryData = country;
                
                // Update flag
                this.selectedFlagInner.className = 'iti__flag iti__' + country.iso2;
                
                // Update input placeholder
                this._updatePlaceholder();
                
                // Trigger change event
                this._triggerCountryChange();
            }
        },

        _getCountryData: function(countryCode) {
            for (var i = 0; i < this.countries.length; i++) {
                if (this.countries[i].iso2 === countryCode) {
                    return this.countries[i];
                }
            }
            return null;
        },

        _updatePlaceholder: function() {
            if (this.options.autoPlaceholder === 'aggressive') {
                var placeholder = this._generatePlaceholder();
                this.telInput.setAttribute('placeholder', placeholder);
            }
        },

        _generatePlaceholder: function() {
            // Simple placeholder generation
            var country = this.selectedCountryData;
            if (country) {
                return '+' + country.dialCode + ' ';
            }
            return '';
        },

        _formatNumber: function() {
            // Basic formatting (simplified)
            var value = this.telInput.value;
            if (value && !value.startsWith('+')) {
                // Auto-add country code if not present
                if (this.selectedCountryData && this.selectedCountryData.dialCode) {
                    this.telInput.value = '+' + this.selectedCountryData.dialCode + ' ' + value;
                }
            }
        },

        _toggleDropdown: function() {
            if (this.countryList.classList.contains('iti__hide')) {
                this._openDropdown();
            } else {
                this._closeDropdown();
            }
        },

        _openDropdown: function() {
            this.countryList.classList.remove('iti__hide');
            this.countryList.setAttribute('aria-expanded', 'true');
            this.dropdownArrow.classList.add('iti__arrow--up');
        },

        _closeDropdown: function() {
            this.countryList.classList.add('iti__hide');
            this.countryList.setAttribute('aria-expanded', 'false');
            this.dropdownArrow.classList.remove('iti__arrow--up');
        },

        _triggerCountryChange: function() {
            var event = new CustomEvent('countrychange');
            this.telInput.dispatchEvent(event);
        },

        // Public methods
        getNumber: function() {
            var value = this.telInput.value.trim();
            if (value && !value.startsWith('+') && this.selectedCountryData) {
                return '+' + this.selectedCountryData.dialCode + value;
            }
            return value;
        },

        getSelectedCountryData: function() {
            return this.selectedCountryData;
        },

        isValidNumber: function() {
            var number = this.getNumber();
            // Simple validation (7-15 digits after country code)
            return /^\+\d{7,15}$/.test(number);
        },

        setCountry: function(countryCode) {
            this._selectCountry(countryCode);
        },

        destroy: function() {
            if (this.container && this.container.parentNode) {
                this.container.parentNode.insertBefore(this.telInput, this.container);
                this.container.parentNode.removeChild(this.container);
            }
        }
    };

    // Factory function
    function intlTelInput(input, options) {
        return new IntlTelInput(input, options);
    }

    // Static methods
    intlTelInput.getCountryData = function() {
        return allCountries.map(function(country) {
            return {
                name: country[0],
                iso2: country[1],
                dialCode: country[2]
            };
        });
    };

    return intlTelInput;
})));